const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statuses={unmarked:'Not marked',present:'Present',excused:'Excused',absent:'Absent',late:'Late'};
const choices=['present','excused','absent'];
let options={},data=null,draft=null,saved=null,error='',loading=false,saving=false,scope='',generation=0,visible=false,dirty=false,tab='attendance',editing=false;
const pendingMarks=new Set();
const clock=()=>options.now?.()??Date.now();
const today=()=>new Date(clock()+8*3600000).toISOString().slice(0,10);
const localTime=now=>new Date(now+8*3600000).toISOString().slice(11,16);
const copy=value=>JSON.parse(JSON.stringify(value));
const teachingHours=s=>s.teachingHours!==undefined?s.teachingHours:s.state==='live'?null:s.durationMinutes/60;
const amount=s=>s.state!=='live'&&s.teacherPresent&&s.rateMinor!==null&&teachingHours(s)!==null?Math.round(teachingHours(s)*s.rateMinor):null;
const money=(minor,currency)=>currency+' '+(minor/100).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const hoursText=value=>value===null||!Number.isFinite(value)?'':String(Number(value.toFixed(4)));
const markedLocal=value=>value?new Date(Date.parse(value)+8*3600000).toISOString():'';
export const attendanceMarkedTime=value=>value?attendanceTime(markedLocal(value).slice(11,16)):'Not recorded';
export function attendanceTime(value){if(!value)return '—';const [hour,minute]=value.split(':').map(Number);return (hour%12||12)+':'+String(minute).padStart(2,'0')+' '+(hour>=12?'PM':'AM');}
const classDate=value=>new Date(value+'T00:00:00Z').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});
export function attendanceCSV(sessions,students=false){
 const rows=[students?['Date','Class','Start','End','Student','Attendance','Marked date (UTC+8)','Marked time (UTC+8)']:['Date','Class','Teacher','Start','End','Teaching attendance','Teaching hours','Hourly rate','Currency','Calculated pay','Payment status','End date']];
 for(const s of [...sessions].sort((a,b)=>a.date.localeCompare(b.date)||a.startTime.localeCompare(b.startTime))){const hours=teachingHours(s),total=amount(s);if(students)for(const row of s.attendees)rows.push([s.date,s.title,attendanceTime(s.startTime),s.state==='live'?'In progress':attendanceTime(s.endTime),row.name,statuses[row.status],markedLocal(row.markedAt).slice(0,10),attendanceMarkedTime(row.markedAt)]);else rows.push([s.date,s.title,s.teacherName||'Teacher Angelo',attendanceTime(s.startTime),s.state==='live'?'In progress':attendanceTime(s.endTime),s.teacherPresent?'Taught':'Not recorded',hours===null?'':(s.teacherPresent?hours:0).toFixed(2),s.rateMinor===null?'':(s.rateMinor/100).toFixed(2),s.currency,total===null?'':(total/100).toFixed(2),s.paid?'Received':total===null?'Not calculated':'Unpaid',s.endDate||s.date]);}
 const cell=value=>{let text=String(value??'');if(/^\s*[=+@\-]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"';};return '\uFEFF'+rows.map(row=>row.map(cell).join(',')).join('\r\n');
}
let month=today().slice(0,7);
function sync(){const session=options.session?.(),next=session?.teacher&&session.connected?'teacher':'';if(next===scope)return;scope=next;generation++;data=null;draft=null;saved=null;error='';loading=false;saving=false;dirty=false;pendingMarks.clear();month=today().slice(0,7);visible=false;tab='attendance';editing=false;}
const active=()=>scope&&String(options.win?.location.hash||globalThis.location?.hash||'').startsWith('#teacher/attendance');
function render(){if(!active())return;const win=options.win||globalThis.window,doc=options.doc||globalThis.document,position=win?.scrollY,focused=doc?.activeElement?.dataset,action=focused?.attendanceAction,id=focused?.attendanceStudent;options.render?.();if(action&&[...choices,'tab-attendance','tab-pay','details'].includes(action))doc?.querySelector?.('[data-attendance-action="'+action+'"]'+(id?'[data-attendance-student="'+id+'"]':''))?.focus?.({preventScroll:true});if(Number.isFinite(position))win.scrollTo?.({top:position,behavior:'instant'});}
export function attendanceConnectionChanged(){sync();}
function setClockFields(record){const [hour,minute]=record.startTime.split(':').map(Number);record.timeText=(hour%12||12)+':'+String(minute).padStart(2,'0');record.period=hour>=12?'PM':'AM';return record;}
const cloneSession=session=>setClockFields({...copy(session),hourlyRate:session.rateMinor===null?null:session.rateMinor/100});
function openSession(session){saved=copy(session);draft=cloneSession(session);dirty=false;pendingMarks.clear();error='';tab='attendance';editing=false;}
export async function refreshAttendance(force=false){sync();if(!scope||loading||saving||data&&!force)return;const version=generation,selected=month;loading=true;error='';try{const value=await options.request('/api/teacher/attendance?month='+encodeURIComponent(selected));if(version===generation&&month===selected){data=value;if(draft?.revision===0)draft.attendees=value.students.map(student=>({...draft.attendees.find(row=>row.studentId===student.id)||{status:'unmarked',markedAt:null},studentId:student.id,name:student.name}));}}catch(e){if(version===generation)error=e.message;}finally{if(version===generation){loading=false;render();}}}
function newRecord(){const date=today();draft=setClockFields({id:crypto.randomUUID(),revision:0,date:date.startsWith(month)?date:month+'-01',title:'IELTS class',state:'completed',startTime:localTime(clock()),endTime:localTime(clock()),endDate:date,startedAt:null,endedAt:null,teachingHours:null,durationMinutes:0,teacherPresent:true,hourlyRate:null,currency:'MNT',paid:false,notes:'',attendees:(data?.students||[]).map(s=>({studentId:s.id,name:s.name,status:'unmarked',markedAt:null}))});saved=null;dirty=false;pendingMarks.clear();error='';tab='attendance';editing=true;}
function preview(){if(!draft)return {hours:null,minor:null};const hours=teachingHours(draft),valid=hours!==null&&Number.isFinite(hours)&&hours>0&&hours<=24&&(draft.teachingHours===undefined||Math.abs(hours*100-Math.round(hours*100))<0.00001);return {hours:valid?hours:null,minor:valid&&draft.teacherPresent&&draft.hourlyRate!==null&&Number.isFinite(draft.hourlyRate)&&draft.hourlyRate>=0?Math.round(hours*Math.round(draft.hourlyRate*100)):null};}
function previews(){const value=preview(),doc=options.doc||document,pay=doc.querySelector('[data-attendance-pay]'),formula=doc.querySelector('[data-attendance-formula]'),paid=doc.querySelector('[data-attendance-field="paid"]');if(pay)pay.textContent=value.minor===null?'—':money(value.minor,draft.currency);if(formula)formula.textContent=value.minor===null?'Enter hours and an amount per hour to see the total.':hoursText(value.hours)+' hours × '+money(Math.round(draft.hourlyRate*100),draft.currency)+' per hour';if(paid)paid.disabled=value.minor===null||saving;}
function basicFields(){return `<div class="attendance-fields"><label>Class date<input type="date" data-attendance-field="date" value="${esc(draft.date)}" max="${today()}" required></label><label>Class time<div class="attendance-time-entry"><input type="text" inputmode="decimal" data-attendance-field="timeText" value="${esc(draft.timeText)}" placeholder="6:30" maxlength="5" pattern="(0?[1-9]|1[0-2])([:.][0-5][0-9])?" aria-label="Class time, for example 6:30" required><select data-attendance-field="period" aria-label="AM or PM"><option ${draft.period==='AM'?'selected':''}>AM</option><option ${draft.period==='PM'?'selected':''}>PM</option></select></div><small>Type 6:30 or 6.30, then choose AM or PM.</small></label><label class="attendance-wide">Session name<input data-attendance-field="title" value="${esc(draft.title)}" maxlength="120" required></label></div>`;}
function payFields(){const value=preview();return `<div class="attendance-fields"><label>Hours worked<input type="number" inputmode="decimal" min="0.01" max="24" step="any" data-attendance-field="teachingHours" value="${esc(hoursText(teachingHours(draft)))}" placeholder="e.g. 1.5"><small>1.5 means one and a half hours.</small></label><label>Amount per hour<input type="number" inputmode="decimal" min="0" max="100000000" step="0.01" data-attendance-field="hourlyRate" value="${draft.hourlyRate===null?'':esc(draft.hourlyRate)}" placeholder="e.g. 20000"></label><label>Currency<select data-attendance-field="currency">${['MNT','PHP','USD'].map(c=>`<option ${draft.currency===c?'selected':''}>${c}</option>`).join('')}</select></label></div><div class="attendance-total"><span>Session total</span><output data-attendance-pay aria-live="polite">${value.minor===null?'—':money(value.minor,draft.currency)}</output><small data-attendance-formula>${value.minor===null?'Enter hours and an amount per hour to see the total.':hoursText(value.hours)+' hours × '+money(Math.round(draft.hourlyRate*100),draft.currency)+' per hour'}</small></div><label class="check-item attendance-paid"><input type="checkbox" data-attendance-field="paid" ${draft.paid?'checked':''} ${value.minor===null?'disabled':''}>Payment received</label>`;}
function rosterHTML(){return draft.attendees.map(row=>`<article class="attendance-student"><div class="attendance-student-heading"><span class="attendance-avatar" aria-hidden="true">${esc((row.name||'?').slice(0,1))}</span><div><strong>${esc(row.name)}</strong>${data.students.some(s=>s.id===row.studentId)?'':'<small>Removed from active roster</small>'}</div><span class="attendance-status attendance-status-${row.status}">${statuses[row.status]}</span></div><div class="attendance-mark-buttons" role="group" aria-label="Attendance for ${esc(row.name)}">${choices.map(status=>`<button type="button" class="button secondary attendance-${status}" data-attendance-action="${status}" data-attendance-student="${row.studentId}" aria-pressed="${row.status===status}">${statuses[status]}</button>`).join('')}</div></article>`).join('')||'<p class="attendance-empty">No students in this session. Add students from Students & class codes, then launch a new session.</p>';}
function counts(session){return choices.map(status=>({status,count:session.attendees.filter(row=>row.status===status||status==='present'&&row.status==='late').length}));}
function formHTML(){if(!draft)return '';const fresh=draft.revision===0,totals=counts(draft),unmarked=draft.attendees.filter(row=>row.status==='unmarked').length;
 if(fresh)return `<section class="card attendance-editor"><div class="section-head"><div><h2>Launch class session</h2><p class="small muted">Choose the date and type the time directly.</p></div><button class="button secondary" type="button" data-attendance-action="cancel" ${saving?'disabled':''}>Cancel</button></div><form data-attendance-form><fieldset ${saving?'disabled':''}>${basicFields()}<details class="attendance-optional"><summary>Hours & pay · optional</summary>${payFields()}</details><p class="small muted">The student list opens when you launch. You can enter hours and pay later.</p><button class="button attendance-primary">${saving?'Launching…':'Launch session & open students'}</button></fieldset></form></section>`;
 return `<section class="card attendance-editor"><div class="attendance-session-heading"><button class="button secondary" type="button" data-attendance-action="cancel" ${saving?'disabled':''}>← Sessions</button><div><h2>${esc(draft.title)}</h2><p class="small muted">${esc(classDate(draft.date))} · ${attendanceTime(draft.startTime)}</p></div><button class="button secondary" type="button" data-attendance-action="details" aria-expanded="${editing}" ${saving?'disabled':''}>${editing?'Hide details':'Edit date & time'}</button></div>${editing?`<form data-attendance-form class="attendance-basic-editor"><fieldset ${saving?'disabled':''}>${basicFields()}<button class="button">Save session details</button></fieldset></form>`:''}<div class="attendance-tabs" role="group" aria-label="Session section"><button type="button" data-attendance-action="tab-attendance" aria-pressed="${tab==='attendance'}">Student attendance</button><button type="button" data-attendance-action="tab-pay" aria-pressed="${tab==='pay'}">My hours & pay</button></div>${tab==='attendance'?`<div class="attendance-counts">${totals.map(({status,count})=>`<span class="attendance-count-${status}"><strong>${count}</strong> ${statuses[status]}</span>`).join('')}<span><strong>${unmarked}</strong> Not marked</span></div><div class="attendance-save-state" role="status" aria-live="polite">${saving||pendingMarks.size?saving?'Saving attendance…':'Attendance changes need saving.':'Tap a status. Attendance saves automatically.'}</div><div class="attendance-roster">${rosterHTML()}</div>`:`<form data-attendance-form><fieldset ${saving?'disabled':''}>${payFields()}<p class="small muted attendance-pay-note">Only the total is calculated: hours × amount per hour. Student attendance does not change your pay.</p><details class="attendance-optional"><summary>Notes & teaching attendance</summary><label class="check-item attendance-teacher"><input type="checkbox" data-attendance-field="teacherPresent" ${draft.teacherPresent?'checked':''}>I taught this session</label><label>Notes<textarea rows="3" maxlength="1000" data-attendance-field="notes">${esc(draft.notes)}</textarea></label></details><button class="button attendance-primary">Save hours & pay</button></fieldset></form>`}</section>`;
}
function sessionsHTML(){const summary=data.summary;return `<section class="card attendance-summary"><div><strong>${data.sessions.length}</strong><span>class sessions</span></div><div><strong>${hoursText(summary.minutes/60)||'0'}</strong><span>hours entered this month</span></div>${Object.entries(summary.payments).map(([currency,p])=>`<div class="attendance-month-total"><strong>${money(p.totalMinor,currency)}</strong><span>total pay · ${money(p.outstandingMinor,currency)} unpaid</span></div>`).join('')}</section><section class="attendance-records"><h2>Your class sessions</h2>${data.sessions.length?`<div class="attendance-session-list">${data.sessions.map(s=>{const totals=counts(s),pay=amount(s),hours=teachingHours(s);return `<article class="card attendance-session-card"><div><p class="attendance-session-date">${esc(classDate(s.date))} · ${attendanceTime(s.startTime)}</p><h3>${esc(s.title)}</h3><div class="attendance-session-counts">${totals.map(({status,count})=>`<span>${count} ${statuses[status].toLowerCase()}</span>`).join('')}</div></div><div class="attendance-session-pay"><strong>${pay===null?'Hours & pay not entered':money(pay,s.currency)}</strong><small>${hours===null?'Enter your hours when ready':hoursText(hours)+' hours'}${s.paid?' · Received':''}</small></div><button class="button secondary" data-attendance-action="edit" data-attendance-id="${s.id}" ${saving?'disabled':''}>Open session →</button></article>`;}).join('')}</div>`:'<div class="card attendance-empty"><h3>Ready for your class?</h3><p>Launch a session, then tap Present, Excused or Absent beside each student.</p></div>'}<details class="attendance-exports"><summary>Export records</summary><div class="button-row"><button class="button secondary" data-attendance-action="export-teaching" ${!data.sessions.length?'disabled':''}>Teaching & pay CSV</button><button class="button secondary" data-attendance-action="export-students" ${!data.sessions.length?'disabled':''}>Student attendance CSV</button></div></details></section>`;}
export function attendancePage(){sync();const head='<div class="page-head attendance-page-head"><div class="eyebrow">TEACHER ANGELO · ATTENDANCE</div><h1>Class sessions.</h1><p>Launch a session. Tap attendance. Enter your hours and pay.</p></div>';if(!scope)return head+'<section class="card">Sign in to your teacher dashboard to open attendance.</section>';if(!data&&!loading&&!error)void refreshAttendance();return head+`${!draft?`<div class="attendance-toolbar"><label class="attendance-month">Month<input type="month" data-attendance-month value="${month}" ${saving?'disabled':''}></label><button class="button attendance-primary" data-attendance-action="launch" ${!data||saving?'disabled':''}>+ Launch class session</button><button class="button secondary" data-attendance-action="refresh" ${loading||saving?'disabled':''}>Refresh</button></div>`:''}${error?`<div class="notice warm" role="alert">${esc(error)}${draft?'<p>Your changes are still here.</p>':''}${pendingMarks.size?'<button class="button secondary" type="button" data-attendance-action="retry-attendance">Retry attendance save</button>':''}</div>`:''}${!data?'<section class="card" role="status">Opening your saved class sessions…</section>':draft?formHTML():sessionsHTML()}`;}
export function mountAttendance(){sync();const next=!!active();if(next&&!visible&&data&&!draft)void refreshAttendance(true);visible=next;}
function classClock(record){const match=/^(0?[1-9]|1[0-2])(?:[.:]([0-5]\d))?$/.exec(String(record.timeText||'').trim());if(!match||!['AM','PM'].includes(record.period))throw new Error('Type a time like 6:30, then choose AM or PM.');return String(Number(match[1])%12+(record.period==='PM'?12:0)).padStart(2,'0')+':'+(match[2]||'00');}
function packetFor(record){const packet=copy(record);packet.startTime=classClock(packet);packet.action=packet.teachingHours!==undefined?'session':'save';if(packet.teachingHours===undefined&&packet.state!=='live'){const end=Date.parse(packet.date+'T'+packet.startTime+':00+08:00')+packet.durationMinutes*60000;if(!Number.isFinite(end))throw new Error('Choose a valid class date.');packet.endTime=localTime(end);packet.endDate=new Date(end+8*3600000).toISOString().slice(0,10);}return packet;}
function applyResult(result,preserveFields=false){const current=draft;saved=copy(result.session);data={month:result.month,sessions:result.sessions,summary:result.summary,students:result.students};month=result.month;draft=preserveFields&&dirty?{...current,revision:result.session.revision}:cloneSession(result.session);draft.attendees=result.session.attendees.map(row=>pendingMarks.has(row.studentId)?{...row,...current.attendees.find(a=>a.studentId===row.studentId)}:row);}
async function saveRecord(){if(saving||!draft||!scope)return false;const version=generation,id=draft.id;let packet;try{packet=packetFor(draft);}catch(e){error=e.message;render();return false;}saving=true;error='';render();try{const result=await options.request('/api/teacher/attendance',{method:'POST',body:JSON.stringify(packet)});if(version!==generation||!scope||draft?.id!==id)return false;dirty=false;pendingMarks.clear();applyResult(result);editing=false;options.toast?.(packet.revision?'Session details saved.':'Session launched. Tap a status beside each student.');return true;}catch(e){if(version===generation)error=e.message;return false;}finally{if(version===generation){saving=false;render();}}}
async function flushMarks(){if(saving||!saved||!draft||!scope||!pendingMarks.size)return;const version=generation,id=draft.id;saving=true;error='';render();try{while(pendingMarks.size&&version===generation&&draft?.id===id){const ids=[...pendingMarks];pendingMarks.clear();const packet=packetFor(cloneSession(saved));packet.attendees=copy(draft.attendees);packet.markIds=ids;try{const result=await options.request('/api/teacher/attendance',{method:'POST',body:JSON.stringify(packet)});if(version!==generation||!scope||draft?.id!==id)return;applyResult(result,true);render();}catch(e){if(version===generation){for(const studentId of ids)pendingMarks.add(studentId);error=e.message;}break;}}}finally{if(version===generation){saving=false;render();}}}
function markStudent(row,status){row.status=status;row.markedAt=new Date(clock()).toISOString();pendingMarks.add(row.studentId);}
export function initAttendance(callbacks){options=callbacks;const doc=callbacks.doc||document,win=callbacks.win||window;sync();
 function changed(event){if(!draft||saving||!scope)return;const target=event.target,field=target.dataset.attendanceField;if(!field)return;draft[field]=['teacherPresent','paid'].includes(field)?target.checked:['teachingHours','hourlyRate'].includes(field)?target.value===''?null:Number(target.value):target.value;if(field==='startTime')setClockFields(draft);if(!draft.teacherPresent||draft.hourlyRate===null||teachingHours(draft)===null){draft.paid=false;const paid=doc.querySelector('[data-attendance-field="paid"]');if(paid)paid.checked=false;}dirty=true;previews();}
 doc.addEventListener('input',changed);doc.addEventListener('change',async event=>{changed(event);if(!event.target.hasAttribute?.('data-attendance-month')||saving)return;if(draft&&(dirty||pendingMarks.size)&&!win.confirm('Close this session without saving your changes?')){event.target.value=month;return;}generation++;draft=null;saved=null;pendingMarks.clear();dirty=false;month=event.target.value;data=null;await refreshAttendance(true);render();});
 doc.addEventListener('submit',async event=>{if(!event.target.matches?.('[data-attendance-form]'))return;event.preventDefault();await saveRecord();});
 doc.addEventListener('click',async event=>{const button=event.target.closest?.('[data-attendance-action]');if(!button||button.disabled||!scope)return;const action=button.dataset.attendanceAction;
  if(choices.includes(action)&&draft?.revision>0){const row=draft.attendees.find(a=>a.studentId===button.dataset.attendanceStudent);if(!row)return;markStudent(row,action);render();await flushMarks();return;}
  if(action==='tab-attendance'||action==='tab-pay'){tab=action==='tab-pay'?'pay':'attendance';render();return;}
  if(saving)return;
  if(action==='retry-attendance'){await flushMarks();return;}
  if(action==='refresh'){await refreshAttendance(true);return;}
  if(action==='launch'||action==='new'){if(draft&&(dirty||pendingMarks.size)&&!win.confirm('Close this session without saving your changes?'))return;newRecord();render();return;}
  if(action==='cancel'){if(draft&&(dirty||pendingMarks.size)&&!win.confirm('Close this session without saving your changes?'))return;draft=null;saved=null;dirty=false;pendingMarks.clear();error='';render();return;}
  if(action==='details'){editing=!editing;render();return;}
  if(action==='edit'){if(draft&&(dirty||pendingMarks.size)&&!win.confirm('Close this session without saving your changes?'))return;const session=data.sessions.find(s=>s.id===button.dataset.attendanceId);if(session){openSession(session);render();}return;}
  if(action.startsWith('export-')){const students=action==='export-students',url=URL.createObjectURL(new Blob([attendanceCSV(data.sessions,students)],{type:'text/csv;charset=utf-8'})),link=doc.createElement('a');link.href=url;link.download='Richmount_'+(students?'Student_Attendance_':'Teaching_Payment_')+month+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 });return {state:()=>({data,draft,saved,month,error,loading,saving,scope,pendingMarks:[...pendingMarks],dirty}),refresh:refreshAttendance};}
